/* map q08 (148 mục) — engine-API đợt 1352-1353 Ch.1353 */
window.__LIBQ=window.__LIBQ||{};window.__LIBQ["pham-nhan-tu-tien"]=window.__LIBQ["pham-nhan-tu-tien"]||{};window.__LIBQ["pham-nhan-tu-tien"]["q08"]=window.__LIBQ["pham-nhan-tu-tien"]["q08"]||{};window.__LIBQ["pham-nhan-tu-tien"]["q08"]["map"]={"updatedAt":"2026-07-23","count":148,"nodes":[{"id":"vung-sa-mac-xa-la","name":"Vùng sa mạc xa lạ","cn":"","capDo":"khac","parentId":null,"blurb":"Vùng đất nơi Hàn Lập xuất hiện sau khi thoát khỏi không gian tiết điểm. Nơi đây có khí hậu khô nóng, bề mặt phủ cát xám và đá vụn, còn bầu trời tồn tại bảy thiên thể thay nhau tạo thành ngày và đêm.","detail":"Hàn Lập nằm bất động tại vùng sa mạc này suốt ba tháng. Ngày đêm dài khoảng gấp ba Nhân Giới, bảy thiên thể lần lượt mang hình thái thái dương vào ban ngày và nguyệt lượng vào ban đêm. Linh khí tại đây không đủ nồng đậm để Hàn Lập xác định chắc chắn rằng mình đã tới Linh Giới.","theLucLienQuan":[],"nguon":["@c1262"]},{"id":"khong-gian-tiet-diem","name":"Không gian tiết điểm","cn":"","capDo":"khac","parentId":null,"blurb":"Tuyến vượt giới mà Hàn Lập và Băng Phượng sử dụng. Không gian phong bạo tại đây phá hủy phần lớn bảo vật hộ thân, chôn vùi Bát Linh Xích và khiến hai người bị tách rời.","detail":"Hàn Lập thoát khỏi không gian tiết điểm và rơi xuống một sa mạc xa lạ, nhưng chưa thể xác định nơi đó có phải Linh Giới hay không. Trong quá trình vượt qua, không gian phong bạo phá hủy tám chín phần bảo vật hộ thân của hắn, chôn vùi Bát Linh Xích và tách hắn khỏi Băng Phượng.","theLucLienQuan":[],"nguon":["@c1262"]},{"id":"thanh-la-sa-mac","name":"Thanh La sa mạc","cn":"","capDo":"vuc","parentId":"linh-gioi","blurb":"Sa mạc rộng lớn mà đoàn xe Thiên Đông Thương Hào đang băng qua.","detail":"Đoàn xe dù đi với tốc độ nhanh nhất vẫn cần khoảng một tháng để vượt sang phía bên kia. Nơi đây ban ngày nóng cháy, ban đêm lạnh thấu xương.","theLucLienQuan":["Thiên Đông Thương Hào"],"nguon":["@c1264"]},{"id":"an-vien-thanh","name":"An Viễn Thành","cn":"","aliases":["Thành An Viễn"],"capDo":"thanh","parentId":"linh-gioi","blurb":"Tòa thành nhỏ thuê Thiên Đông Thương Hào vận chuyển một lô hàng quan trọng.","detail":"Thành chủ bỏ ra lượng lớn linh thạch để thuê vận chuyển lô hàng được cho là liên quan trực tiếp tới an nguy của thành. Hà phu nhân đã tới đây trước đoàn xe, còn Ngũ thiếu gia từng được đưa tới đây tu luyện.","theLucLienQuan":["Thiên Đông Thương Hào"],"nguon":["@c1264","@c1275"]},{"id":"sa-mac-hoang-vu","name":"Sa mạc hoang vu","cn":"","aliases":[],"capDo":"khac","parentId":"linh-gioi","blurb":"Vùng sa mạc nơi Hàn Lập chôn phần lớn trọng bảo và túi linh thú khi chưa thể vận dụng pháp lực.","detail":"Hàn Lập chôn các túi trữ vật và túi linh thú sâu hơn mười trượng tại đây, đồng thời để Phệ Kim Trùng, Lục Dực Sương Công và Đề Hồn Thú canh giữ, chờ ngày phục hồi pháp lực quay lại thu hồi.","theLucLienQuan":[],"nguon":["@c1265"]},{"id":"thien-nguyen-canh","name":"Thiên Nguyên Cảnh","cn":"","capDo":"vuc","parentId":"linh-gioi","blurb":"Khu vực rộng lớn tại Linh giới, có hơn một trăm thành thị lớn nhỏ đặt chi nhánh của Thiên Đông Thương Hào.","detail":"Thiên Đông Thương Hào là một trong ba hiệu buôn lớn nhất tại Thiên Nguyên Cảnh. Việc Hàn Lập không biết danh tiếng của hiệu buôn khiến Liễu nhi nhận xét hắn không phải người bản địa.","theLucLienQuan":["Thiên Đông Thương Hào"],"nguon":["@c1266"]},{"id":"thien-nguyen-thanh-thanh","name":"Thiên Nguyên Thánh Thành","cn":"","capDo":"thanh","parentId":"thien-nguyen-canh","blurb":"Thánh thành thuộc Thiên Nguyên Cảnh, nơi đặt tổng bộ của Thiên Đông Thương Hào.","detail":"Thiên Nguyên Thánh Thành là trung tâm đặt tổng bộ của một trong ba hiệu buôn lớn nhất Thiên Nguyên Cảnh.","theLucLienQuan":["Thiên Đông Thương Hào"],"nguon":["@c1266"]},{"id":"cau-lu-son","name":"Cẩu Lũ sơn","cn":"","capDo":"khac","parentId":"thien-nguyen-canh","blurb":"Ngọn núi và nơi xuất thân của Nam Kỳ Tử cùng nhóm tu sĩ chuyên tu thần thông khu trùng.","detail":"Các tu sĩ xuất thân từ Cẩu Lũ sơn chịu quy củ hạn chế và không ra tay với yêu trùng nếu chưa bị chúng chủ động công kích.","theLucLienQuan":["Cẩu Lũ sơn"],"nguon":["@c1266"]},{"id":"khu-vuc-trung-tam-quy-xa-doi","name":"Khu vực trung tâm quy xa đội","cn":"","capDo":"khac","parentId":"sa-mac-hoang-vu","blurb":"Vị trí cự quy chở Hàn Lập nằm bên trong vòng phòng ngự của quy xa đội.","detail":"Đây ban đầu là khu vực an toàn nhất khi các cự quy tạo tuyến chắn và Sa Trùng Thú bao vây đội xe. Hàn Lập cùng lão giả phu xe ở lại đây để quan sát trận chiến.","theLucLienQuan":["Quy xa đội"],"nguon":["@c1267"]},{"id":"thanh-tay-an-vien-thanh","name":"Thành tây An Viễn Thành","cn":"","capDo":"khac","parentId":"an-vien-thanh","blurb":"Khu vực phía tây An Viễn Thành, nơi Phương phu nhân thuê khách điếm làm điểm hội hợp.","detail":"Sau khi giao hàng, đoàn Thiên Đông Thương Hào được Trương Bản dẫn về khu vực này để gặp Phương phu nhân.","theLucLienQuan":["Thiên Đông Thương Hào"],"nguon":["@c1270"]},{"id":"nhu-van-khach-tan","name":"Như Vân Khách Tàn","cn":"","aliases":["Như Vân Khách Hoa"],"capDo":"khac","parentId":"thanh-tay-an-vien-thanh","blurb":"Khách điếm lớn tại thành tây An Viễn Thành được Phương phu nhân thuê trọn.","detail":"Nơi này được dùng làm điểm hội hợp của đoàn Thiên Đông Thương Hào sau khi hoàn tất việc giao hàng.","theLucLienQuan":["Thiên Đông Thương Hào"],"nguon":["@c1270"]},{"id":"kho-hang-an-vien-thanh","name":"Kho hàng An Viễn Thành","cn":"","capDo":"khac","parentId":"an-vien-thanh","blurb":"Khu kho hàng có cổng chào cao và thị vệ mang binh khí canh gác nghiêm mật.","detail":"Thiên Đông Thương Hào giao toàn bộ hàng hóa tại đây, hoàn tất thủ tục nghiệm thu và nhận biên lai trước khi tới thành tây.","theLucLienQuan":["Thiên Đông Thương Hào","An Viễn Thành"],"nguon":["@c1270"]},{"id":"tam-hoang-canh","name":"Tam Hoàng Cảnh","cn":"","aliases":["Tam Cảnh"],"capDo":"vuc","parentId":"linh-gioi","blurb":"Tổng thể ba vùng lãnh thổ của nhân tộc tại Linh Giới.","detail":"Tam Hoàng Cảnh gồm Thiên Nguyên Cảnh, Huyền Vũ Cảnh và Thiên Linh Cảnh, lần lượt do Thiên Nguyên Thánh Hoàng, Huyền Vũ Phách Hoàng và Thiên Diệu Linh Hoàng thống trị.","theLucLienQuan":["Nhân tộc Tam Hoàng Cảnh"],"nguon":["@c1272"]},{"id":"huyen-vu-canh","name":"Huyền Vũ Cảnh","cn":"","capDo":"vuc","parentId":"tam-hoang-canh","blurb":"Một trong ba vùng lãnh thổ lớn của nhân tộc tại Linh Giới.","detail":"Huyền Vũ Cảnh do Huyền Vũ Phách Hoàng khống chế. Chủ thành của vùng được xây trên lưng cự quy Tham linh và đảm nhiệm một trận nhãn của siêu đại pháp trận.","theLucLienQuan":["Nhân tộc Tam Hoàng Cảnh"],"nguon":["@c1272"]},{"id":"thien-linh-canh","name":"Thiên Linh Cảnh","cn":"","capDo":"vuc","parentId":"tam-hoang-canh","blurb":"Một trong ba vùng lãnh thổ lớn của nhân tộc tại Linh Giới.","detail":"Thiên Linh Cảnh do Thiên Diệu Linh Hoàng khống chế. Thiên Linh Thành tại đây được dựng trên Kình Thiên Linh Thụ, một trận nhãn của siêu đại pháp trận.","theLucLienQuan":["Nhân tộc Tam Hoàng Cảnh"],"nguon":["@c1272"]},{"id":"that-yeu-chi-dia","name":"Thất Yêu Chi Địa","cn":"","aliases":["Thất Địa"],"capDo":"vuc","parentId":"linh-gioi","blurb":"Bảy vùng lãnh thổ của Yêu Tộc do Thất Yêu Vương thống trị.","detail":"Thất Yêu Chi Địa cùng Tam Hoàng Cảnh tạo thành khu vực nhân–yêu được siêu đại pháp trận che chở trong Linh Giới.","theLucLienQuan":["Yêu Tộc Thất Yêu Chi Địa"],"nguon":["@c1272"]},{"id":"thien-nguyen-thanh","name":"Thiên Nguyên Thành","cn":"","capDo":"thanh","parentId":"thien-nguyen-canh","blurb":"Chủ thành của Thiên Nguyên Cảnh, được xây tại Thiên Nguyên Thánh Sơn.","detail":"Thiên Nguyên Thành có diện tích tương đương một tiểu quốc tại Nhân Giới và là một trong ba chủ thành đảm nhiệm trận nhãn phía nhân tộc.","theLucLienQuan":["Nhân tộc Tam Hoàng Cảnh"],"nguon":["@c1272"]},{"id":"thien-nguyen-thanh-son","name":"Thiên Nguyên Thánh Sơn","cn":"","capDo":"khac","parentId":"thien-nguyen-canh","blurb":"Thánh sơn nơi Thiên Nguyên Thành được xây dựng.","detail":"Thiên Nguyên Thánh Sơn là nơi đặt Thiên Nguyên Thành và đồng thời đảm nhiệm một trận nhãn phía nhân tộc của siêu đại pháp trận.","theLucLienQuan":["Nhân tộc Tam Hoàng Cảnh"],"nguon":["@c1272"]},{"id":"huyen-vu-thanh","name":"Huyền Vũ Thành","cn":"","capDo":"thanh","parentId":"huyen-vu-canh","blurb":"Chủ thành của Huyền Vũ Cảnh, được xây trên lưng cự quy Tham linh.","detail":"Huyền Vũ Thành có thể theo cự quy chậm rãi di chuyển trên biển và là một trận nhãn phía nhân tộc của siêu đại pháp trận.","theLucLienQuan":["Nhân tộc Tam Hoàng Cảnh"],"nguon":["@c1272"]},{"id":"cu-quy-tham-linh","name":"Cự quy Tham linh","cn":"","capDo":"khac","parentId":"huyen-vu-canh","blurb":"Cổ quy khổng lồ mang Huyền Vũ Thành trên lưng.","detail":"Cự quy Tham linh có từ thời viễn cổ, có thể chậm rãi di chuyển trên biển và cùng Huyền Vũ Thành đảm nhiệm một trận nhãn của siêu đại pháp trận.","theLucLienQuan":["Nhân tộc Tam Hoàng Cảnh"],"nguon":["@c1272"]},{"id":"thien-linh-thanh","name":"Thiên Linh Thành","cn":"","capDo":"thanh","parentId":"thien-linh-canh","blurb":"Chủ thành của Thiên Linh Cảnh, được xây trên Kình Thiên Linh Thụ.","detail":"Thiên Linh Thành được dựng trực tiếp trên cổ thụ có đường kính hàng trăm dặm và là một trận nhãn phía nhân tộc của siêu đại pháp trận.","theLucLienQuan":["Nhân tộc Tam Hoàng Cảnh"],"nguon":["@c1272"]},{"id":"kinh-thien-linh-thu","name":"Kình Thiên Linh Thụ","cn":"","capDo":"khac","parentId":"thien-linh-canh","blurb":"Cổ thụ khổng lồ làm nền móng cho Thiên Linh Thành.","detail":"Kình Thiên Linh Thụ có đường kính hàng trăm dặm, được đồn có thể nối thẳng tới Tiên Giới và đảm nhiệm một trận nhãn phía nhân tộc của siêu đại pháp trận.","theLucLienQuan":["Nhân tộc Tam Hoàng Cảnh"],"nguon":["@c1272"]},{"id":"tay-vien-nhu-van-khach-diem","name":"Tây viện","cn":"","capDo":"khac","parentId":"nhu-van-khach-tan","blurb":"Khu viện phía tây của Như Vân Khách Điếm, được Thiên Đông Thương Hào bao trọn làm nơi lưu trú.","detail":"Tây viện gồm nhiều sân viện và có một tiểu viện u nhã nơi Phương phu nhân chờ gặp Hàn Lập. Hai đại hán đứng canh bên ngoài tiểu viện.","theLucLienQuan":["Thiên Đông Thương Hào"],"nguon":["@c1273"]},{"id":"san-cua-phuong-phu-nhan","name":"Sân của Phương phu nhân","cn":"","capDo":"khac","parentId":"an-vien-thanh","blurb":"Khoảng sân thuộc nơi ở của Phương phu nhân tại An Viễn Thành.","detail":"Đây là nơi hai thiếp thân thị vệ theo lệnh Phương phu nhân thử sức Hàn Lập trước khi cho hắn vào phòng gặp bà.","theLucLienQuan":["Thiên Đông Thương Hào"],"nguon":["@c1274"]},{"id":"tuong-thanh-phia-nam-an-vien-thanh","name":"Tường thành phía Nam An Viễn Thành","cn":"","capDo":"khac","parentId":"an-vien-thanh","blurb":"Khu tường thành có tháp cao dùng để quan sát thú triều ở phía ngoài.","detail":"Thành chủ đứng tại tháp cao ở khu vực này để tiếp nhận báo cáo trinh sát và theo dõi tình hình ba đàn thú.","theLucLienQuan":["Lực lượng phòng thủ An Viễn Thành"],"nguon":["@c1275"]},{"id":"hac-lang-son-mach","name":"Hắc Lang Sơn Mạch","cn":"","capDo":"vuc","parentId":null,"blurb":"Sơn mạch được xác định là nơi đàn Thanh Lang thú tiến ra tấn công An Viễn Thành.","detail":"Báo cáo trinh sát của lực lượng phòng thủ xác định đàn Thanh Lang trong thú triều xuất phát từ khu vực này.","theLucLienQuan":[],"nguon":["@c1275"]},{"id":"phi-thuy-thao-nguyen","name":"Phỉ Thúy Thảo Nguyên","cn":"","capDo":"vuc","parentId":null,"blurb":"Thảo nguyên được nhắc trong báo cáo trinh sát về nguồn xuất phát của Xích Mãng thú.","detail":"Khu vực này gắn với đợt Xích Mãng đang tiến về An Viễn Thành trong ba đợt thú triều.","theLucLienQuan":[],"nguon":["@c1275"]},{"id":"tuong-thanh-phia-thanh-lang","name":"Tường thành phía Thanh Lang","cn":"","capDo":"khac","parentId":"an-vien-thanh","blurb":"Mặt tường thành đối diện biển Thanh Lang và khu vực tập trung quân phòng thủ.","detail":"Phía ngoài mặt thành là đàn Thanh Lang đông tới hàng vạn và có thể chứa nhiều cá thể biến dị. Một quảng trường lớn gần đây được dùng để tập kết, chỉnh biên lực lượng trước khi họ lên thành.","theLucLienQuan":["Lực lượng phòng thủ An Viễn Thành","Thiên Đông Thương Hào"],"nguon":["@c1276"]},{"id":"tuong-thanh-phia-xich-mang","name":"Tường thành phía Xích Mãng","cn":"","capDo":"khac","parentId":"an-vien-thanh","blurb":"Mặt tường thành nơi Hàn Lập và Trương Khuê quan sát biển Xích Mãng.","detail":"Đàn Xích Mãng bên ngoài khu vực này còn đông hơn Thanh Lang. Trong đàn có nhiều cự mãng biến dị dài hơn mười trượng, đủ sức quấn hoặc nuốt người bình thường.","theLucLienQuan":["Lực lượng phòng thủ An Viễn Thành"],"nguon":["@c1276"]},{"id":"quang-truong-tap-ket-an-vien-thanh","name":"Quảng trường tập kết An Viễn Thành","cn":"","capDo":"khac","parentId":"an-vien-thanh","blurb":"Quảng trường lớn gần mặt thành phía Thanh Lang, được dùng làm nơi tập kết quân phòng thủ.","detail":"Hàng vạn người tập trung tại đây trước trận công thành. Thống lĩnh thủ vệ tổ chức người có tọa kỵ thành lực lượng kỵ binh, đồng thời cho phân phát binh khí và khôi giáp cho lực lượng phàm nhân.","theLucLienQuan":["Lực lượng phòng thủ An Viễn Thành","Thiên Đông Thương Hào","Kim Ngọc Tông"],"nguon":["@c1276"]},{"id":"an-xa-thanh","name":"An Xa thành","cn":"","aliases":[],"capDo":"thanh","parentId":null,"blurb":"Thành trì bị đàn thanh lang và xích mãng vây đánh từ nhiều hướng.","detail":"Chiến sự kéo dài từ giữa trưa tới chiều tối. Thanh lang công kích một phía, xích mãng giao chiến tại phía đối diện, còn cự lang biến dị leo lên tường thành và buộc các luyện thể tu sĩ phải xuất chiến.","theLucLienQuan":["Lực lượng phòng thủ An Viễn Thành","Thiên Đông Thương Hào"],"nguon":["@c1277"]},{"id":"doan-tuong-thanh-cua-han-lap","name":"Đoạn tường thành của Hàn Lập","cn":"","aliases":[],"capDo":"khac","parentId":"an-xa-thanh","blurb":"Đoạn thành do hơn một nghìn binh sĩ và hai trăm hộ vệ Thiên Đông Thương Hào phối hợp phòng thủ.","detail":"Hàn Lập và Đỗ Khiếu được bố trí bảo vệ viên quan quân chỉ huy tại đây. Sau nhiều giờ giao chiến, hơn mười cự lang biến dị xuất hiện và tập kích khu vực tường thành.","theLucLienQuan":["Lực lượng phòng thủ An Viễn Thành","Thiên Đông Thương Hào"],"nguon":["@c1277"]},{"id":"cac-thanh-dau-lan-can","name":"Các thành đầu lân cận","cn":"","capDo":"khac","parentId":"an-vien-thanh","blurb":"Bốn, năm đoạn thành nằm gần vị trí phòng thủ của Hàn Lập cùng lúc bị đàn yêu lang công kích.","detail":"Mỗi đoạn thành lân cận bị khoảng nghìn yêu lang bao vây, khiến toàn khu vực rơi vào hỗn loạn. Tình hình tại các phòng tuyến này làm thủ quân dao động và lo ngại thành trì không thể chống đỡ.","theLucLienQuan":["Lực lượng phòng thủ An Viễn Thành"],"nguon":["@c1278"]},{"id":"tuong-thanh-an-vien-thanh","name":"Tường thành An Viễn Thành","cn":"","capDo":"khac","parentId":"an-vien-thanh","blurb":"Phòng tuyến bao quanh An Viễn Thành, chịu thiệt hại nặng trong đợt cuồng thú triều.","detail":"Một đoạn tường cùng cổng đá bị cự xà phá nát, trong khi mặt đất chuyển đen và bốc mùi do hắc sắc độc vụ của phi mãng biến dị. Nhóm luyện thể sĩ có Hàn Lập được điều tới đây để kiềm chế cự mãng và hỗ trợ quân phòng thủ.","theLucLienQuan":["Lực lượng phòng thủ An Viễn Thành","Thiên Đông Thương Hào","Linh đội"],"nguon":["@c1279"]},{"id":"doanh-dia-vung-doi-nui","name":"Doanh địa vùng đồi núi","cn":"","capDo":"khac","parentId":null,"blurb":"Khu trú ẩn tạm thời của những người sống sót sau khi An Viễn Thành thất thủ. Doanh địa nằm giữa vùng đồi núi và kéo dài vài dặm.","detail":"Nơi trú ẩn gồm một quần thể lều trại và nhà gỗ dựng tạm thời. Tần Kỳ Quyền đưa Hàn Lập và Đại Nhi tới đây để gặp chủ nhân của mình, đồng thời hy vọng tìm được thân nhân của Đại Nhi trong số các phàm nhân chạy thoát.","theLucLienQuan":[],"nguon":["@c1282"]},{"id":"cac-dai-thanh-cua-nhan-loai","name":"Các đại thành của nhân loại","cn":"","capDo":"thanh","parentId":null,"blurb":"Những thành thị lớn của nhân loại có lượng tu sĩ cấp thấp ra vào cực kỳ đông đảo.","detail":"Mỗi ngày có thể có khoảng trăm vạn tu sĩ cấp thấp ra vào các đại thành, khiến thú đàn không dám tùy tiện tấn công như đối với những thành thị nhỏ do phàm nhân kiểm soát.","theLucLienQuan":["Nhân tộc Tam Hoàng Cảnh"],"nguon":["@c1283"]},{"id":"rung-cay-cach-an-vien-thanh-van-dam","name":"Rừng cây cách An Viễn Thành vạn dặm","cn":"","capDo":"khac","parentId":null,"blurb":"Khu rừng nằm cách An Viễn Thành khoảng vạn dặm, nơi diễn ra cuộc truy sát giữa hai yêu cầm và Tử bào đại hán.","detail":"Sau khi vật phi hành mất tác dụng, Tử bào đại hán tăng tốc lao xuống, tránh đợt gai vàng và lôi quang rồi lẩn vào khu rừng này.","theLucLienQuan":[],"nguon":["@c1283"]},{"id":"cuu-huyen-minh-ngoc-dam","name":"Cửu Huyền Minh Ngọc Đàm","cn":"","aliases":["Cửu Huyền Ngọc Minh Đàm","Cửu Minh Ngọc Huyền Đàm"],"capDo":"khac","parentId":null,"blurb":"Linh đàm nằm sâu trong địa bàn Kim Ngọc Tông, có thể kích phát thân thể và hỗ trợ luyện thể sĩ vượt bình cảnh.","detail":"Lực lượng trong đàm ít tác dụng với tu tiên giả thông thường nhưng hữu ích với người luyện thể. Hiệu quả chỉ xuất hiện trong lần ngâm đầu tiên; Hàn Lập xem đây là cơ hội rút ngắn hơn mười năm khổ tu Minh Vương Quyết.","theLucLienQuan":["Kim Ngọc Tông"],"nguon":["@c1285"]},{"id":"sao-huyet-yeu-thu","name":"Sào huyệt yêu thú","cn":"","capDo":"khac","parentId":null,"blurb":"Sào huyệt có Thất Diệp Âm Huyết Chi Thảo được kim hành cấm chế bảo vệ.","detail":"Nhóm Tần Kỳ Quyền dự định lợi dụng thời điểm thú triều khiến lực lượng yêu thú canh giữ suy giảm để tiến vào. Tuy nhiên, việc An Viễn Thành bị công phá quá sớm khiến họ không chắc số yêu thú tại đây đã giảm nhiều như dự tính.","theLucLienQuan":[],"nguon":["@c1285"]},{"id":"go-dat-cach-thanh-hon-tram-dam","name":"Gò đất cách thành hơn trăm dặm","cn":"","capDo":"khac","parentId":null,"blurb":"Gò đất nơi Triệu thành chủ bố trí ba yêu thú phục kích đoàn hộ tống.","detail":"Tại đây, các luyện thể sĩ cùng cự lang bị sát hại và thi thể bị yêu thú ăn sạch để xóa dấu vết. Hàn Lập sau đó hiện thân, phá cuộc tập kích và trảm sát tam yêu.","theLucLienQuan":[],"nguon":["@c1286"]},{"id":"khu-vuc-cua-nhan-loai","name":"Khu vực của Nhân loại","cn":"","capDo":"vuc","parentId":null,"blurb":"Lãnh địa của nhân loại, nơi cao giai yêu tu bị ràng buộc bởi hiệp nghị giữa hai bên.","detail":"Cao giai yêu tu tiến vào khu vực này trái hiệp nghị có thể bị tu sĩ nhân loại truy sát. Phiệt cô cô vì thế phải tránh bị thương nặng và để lộ yêu khí.","theLucLienQuan":["Nhân tộc","Hắc Phượng Tộc"],"nguon":["@c1287"]},{"id":"ngu-duong-thanh","name":"Ngu Dương Thành","cn":"","aliases":[],"capDo":"thanh","parentId":"thien-nguyen-canh","blurb":"Cổ thành bậc trung tại Thiên Nguyên Cảnh, tồn tại từ thời Tam Cảnh sơ khai. Thành nổi tiếng với truyền thống luyện thể, khả năng chế tạo linh cụ và lực lượng Luyện thể sĩ đông đảo.","detail":"Ngu Dương Thành đã vượt qua nhiều lần thú triều nhờ tập trung đông đảo Luyện thể sĩ. Thành có nhiều tông môn luyện thể, ngành sản xuất và đấu giá linh cụ phát triển, đồng thời được kể là quê hương của Thiên Nguyên Thánh Hoàng. Trung tâm thành đặt Thánh Tháp, nơi lưu giữ lượng lớn pháp môn cùng tâm đắc luyện thể.","theLucLienQuan":["Long Hưng Thương Hội"],"nguon":["@c1288"]},{"id":"thanh-thap","name":"Thánh Tháp","cn":"","aliases":[],"capDo":"khac","parentId":"ngu-duong-thanh","blurb":"Công trình nằm tại trung tâm Ngu Dương Thành, chuyên lưu trữ pháp môn và tâm đắc tu luyện. Nơi đây được xem là một kho tri thức Luyện Thể Thuật hàng đầu Thiên Nguyên Cảnh.","detail":"Thánh Tháp tập trung lượng lớn kinh sách có nội dung phong phú về Luyện Thể Thuật. Kho tàng này phản ánh truyền thống luyện thể lâu đời và hệ thống truyền thừa đa dạng của Ngu Dương Thành.","theLucLienQuan":[],"nguon":["@c1288"]},{"id":"phe-tich-an-vien-thanh","name":"Phế tích An Viễn Thành","cn":"","capDo":"thanh","parentId":"an-vien-thanh","blurb":"Di tích còn lại của An Viễn Thành sau khi thành bị phá hủy.","detail":"Hàn Lập mất khoảng nửa năm đi từ Ngu Dương Thành đến vùng phụ cận phế tích. Thành cũ vẫn phủ bụi và không có thay đổi đáng kể sau nhiều năm.","theLucLienQuan":["Lực lượng phòng thủ An Viễn Thành"],"nguon":["@c1289"]},{"id":"son-mon-kim-ngoc-tong","name":"Sơn môn Kim Ngọc Tông","cn":"","capDo":"khac","parentId":null,"blurb":"Sơn môn của Kim Ngọc Tông, nơi Hàn Lập tìm gặp Tần Kỳ Quyền.","detail":"Hàn Lập mất khoảng một năm tìm tới nơi này. Tại đây, Tần Kỳ Quyền thực hiện lời hứa và an bài cho hắn vào Cửu Huyền Minh Ngọc Đàm.","theLucLienQuan":["Kim Ngọc Tông"],"nguon":["@c1289"]},{"id":"sa-mac-cat-xanh-xam","name":"Sa mạc cát xanh xám","cn":"","capDo":"khac","parentId":"linh-gioi","blurb":"Sa mạc nơi Lục Dực Sương Công săn Phi Hạt, cắt đứt quyền khống chế của Hàn Lập rồi tự rời đi.","detail":"Túi trữ vật, ba túi linh thú và các vỏ xác linh trùng của Hàn Lập từng được chôn dưới lớp cát xanh xám. Sau khi thu hồi đồ vật, hắn chôn kín những vỏ xác còn lại và xóa dấu vết trước khi lên đường.","theLucLienQuan":[],"nguon":["@c1290"]},{"id":"toa-thanh-gan-yeu-thu-chi-dia","name":"Tòa Thành gần Yêu Thú Chi Địa","cn":"","capDo":"thanh","parentId":"thien-nguyen-canh","blurb":"Một thành trì nổi tiếng gần Yêu Thú Chi Địa, nằm cách nơi Hàn Lập khởi hành khoảng ngàn vạn dặm.","detail":"Tòa thành nằm gần một cổng giáp ranh thuộc Thiên Nguyên Cảnh và là mục tiêu Hàn Lập hướng tới sau khi rời sa mạc.","theLucLienQuan":["Nhân tộc"],"nguon":["@c1290"]},{"id":"yeu-thu-chi-dia","name":"Yêu Thú Chi Địa","cn":"","capDo":"vuc","parentId":"linh-gioi","blurb":"Khu vực tiếp giáp Thiên Nguyên Cảnh và chia sẻ với nơi này một vùng biên rộng lớn.","detail":"Vùng giáp ranh gần Yêu Thú Chi Địa thường xuất hiện Yêu Thú, Man Hoang Cổ Thú và Bán Yêu Nhân. Khu vực này phần lớn chưa do thế lực nào chính thức quản lý.","theLucLienQuan":["Yêu tộc","Nhân tộc"],"nguon":["@c1290"]},{"id":"vung-bien-canh-nhan-yeu","name":"Vùng biên cảnh Nhân–Yêu","cn":"","capDo":"vuc","parentId":"linh-gioi","blurb":"Vùng giáp ranh chưa được Nhân tộc và Yêu tộc chính thức khai phá, giàu tài nguyên nhưng tập trung nhiều sinh vật cùng cường giả nguy hiểm.","detail":"Khu vực rộng lớn này phần nhiều không thuộc quyền quản lý chính thức của thế lực nào. Yêu Thú, Man Hoang Cổ Thú, Bán Yêu Nhân, tu sĩ và yêu tu cấp cao đều có thể xuất hiện, trong khi lời đồn còn nhắc tới Linh Tộc, thượng cổ cự nhân và Chân Long. Linh mạch, linh dược cùng các đặc sản quý hiếm vẫn thu hút tu sĩ và Luyện thể sĩ tới tìm cơ duyên bất chấp hiểm nguy. Hàn Lập tới được vùng biên sau hơn một năm liên tục đi bộ.","theLucLienQuan":["Nhân tộc","Yêu tộc"],"nguon":["@c1290"]},{"id":"lac-nhat-chi-mo","name":"Lạc Nhật Chi Mộ","cn":"","capDo":"vuc","parentId":"linh-gioi","blurb":"Lòng vực khổng lồ nằm giữa địa bàn sinh sống của nhân tộc và yêu tộc, tương truyền được tạo thành khi một mặt trời rơi xuống trong Chân linh chi chiến.","detail":"Lạc Nhật Chi Mộ chứa vô số sơn mạch, hàng chục hồ rộng lớn, rừng rậm và bình nguyên. Khu vực rộng tới mức cao giai tu sĩ dùng pháp bảo toàn lực bay ngang cũng cần khoảng một năm.","theLucLienQuan":["Nhân tộc","Yêu tộc"],"nguon":["@c1291"]},{"id":"lac-nhat-thanh-nhan-toc","name":"Lạc Nhật Thành của nhân tộc","cn":"","capDo":"thanh","parentId":"lac-nhat-chi-mo","blurb":"Một trong ba đại thành của Thiên Nguyên Cảnh, nằm quanh Lạc Nhật Chi Mộ và do nhân tộc nắm giữ.","detail":"Thành tập trung đông đảo tu sĩ, luyện thể sĩ và phàm nhân, đồng thời có tu sĩ Hóa Thần kỳ tọa trấn. Hoạt động giao dịch trong thành bao gồm tài liệu yêu thú, pháp khí, linh cụ, đan dược và nhiều loại bảo vật.","theLucLienQuan":["Nhân tộc"],"nguon":["@c1291"]},{"id":"lac-nhat-thanh-yeu-toc","name":"Lạc Nhật Thành của yêu tộc","cn":"","capDo":"thanh","parentId":"lac-nhat-chi-mo","blurb":"Yêu thành cùng tên Lạc Nhật Thành nằm tại địa bàn yêu tộc trong Lạc Nhật Chi Mộ.","detail":"Tòa thành được truyền là rộng lớn và tráng lệ hơn Lạc Nhật Thành của nhân tộc, đồng thời có nhiều cao giai yêu tu sinh sống.","theLucLienQuan":["Yêu tộc"],"nguon":["@c1291"]},{"id":"tam-khu-vuc-lac-nhat-thanh","name":"Tám khu vực của Lạc Nhật Thành","cn":"","capDo":"khac","parentId":"lac-nhat-thanh-nhan-toc","blurb":"Cấu trúc nội thành Lạc Nhật Thành gồm ba khu dành cho phàm nhân và năm khu dành cho tu tiên giả cùng luyện thể sĩ.","detail":"Năm khu dành cho tu tiên giả và luyện thể sĩ gồm một khu trung tâm cùng bốn khu vực bao quanh, phục vụ cư trú và giao dịch.","theLucLienQuan":["Nhân tộc"],"nguon":["@c1291"]},{"id":"khu-trung-tam-lac-nhat-thanh","name":"Khu trung tâm Lạc Nhật Thành","cn":"","capDo":"khac","parentId":"lac-nhat-thanh-nhan-toc","blurb":"Khu giao dịch cao cấp của Lạc Nhật Thành, tập trung tinh phẩm linh cụ, đỉnh bậc bảo vật và các đại hiệu buôn.","detail":"Theo Điền Hưng, khu trung tâm có thể mua bán nhiều bảo vật quý hiếm, thậm chí có đại hiệu buôn bán Linh Bảo.","theLucLienQuan":["Nhân tộc"],"nguon":["@c1291"]},{"id":"lac-nhat-thanh","name":"Lạc Nhật Thành","cn":"","capDo":"thanh","parentId":"linh-gioi","blurb":"Thành trì nơi Hàn Lập tìm mua linh cụ và vật liệu luyện thể.","detail":"Lạc Nhật Thành có thành chủ mang tu vi Hóa Thần, nhưng Hoàng Lương Linh Quân mới được Điền Hưng xem là đệ nhất tu sĩ tại địa phương. Linh xa của vị Hợp Thể tu sĩ này bay qua thành và khiến cả tu sĩ lẫn phàm nhân chú ý.","theLucLienQuan":[],"nguon":["@c1292"]},{"id":"khung-vu-cat","name":"Khung Vũ Cát","cn":"","capDo":"khac","parentId":"lac-nhat-thanh","blurb":"Cửa hàng tại Lạc Nhật Thành chuyên kinh doanh vật liệu và đồ vật đặc thù.","detail":"Khung Vũ Cát do Tư lão quản lý, có hai quái thú màu đỏ giống thằn lằn giữ cửa. Bên trong cửa hàng gần như trống không, có cầu thang dẫn lên tầng trên, nơi cất giữ hai hộp vật liệu được mang xuống cho Hàn Lập xem.","theLucLienQuan":[],"nguon":["@c1292"]},{"id":"rung-nguyen-thuy-lac-nhat-chi-mo","name":"Rừng nguyên thủy trong Lạc Nhật Chi Mộ","cn":"","capDo":"khac","parentId":"lac-nhat-chi-mo","blurb":"Khu rừng rậm rạp trong Lạc Nhật Chi Mộ, nơi Hàn Lập bắt đầu săn giết yêu thú.","detail":"Rừng có cây cao ba bốn mươi trượng, dây leo và cây cối dày đặc, thường vang tiếng yêu thú. Hàn Lập từng giết một con cự hùng một sừng tại đây bằng Địa Giao Cân.","theLucLienQuan":[],"nguon":["@c1293"]},{"id":"day-nui-sau-lac-nhat-chi-mo","name":"Dãy núi sâu trong Lạc Nhật Chi Mộ","cn":"","capDo":"khac","parentId":"lac-nhat-chi-mo","blurb":"Khu vực núi non trong Lạc Nhật Chi Mộ mà Hàn Lập đặt chân tới sau ba tháng săn bắt.","detail":"Tại khu vực này, Hàn Lập giết hơn hai mươi viên hầu xanh và một yêu hầu ba đầu cấp Kết Đan bằng trường thương xám bạc.","theLucLienQuan":[],"nguon":["@c1293"]},{"id":"phien-son-mach","name":"Phiến sơn mạch","cn":"","capDo":"vuc","parentId":null,"blurb":"Sơn mạch nơi Hàn Lập gặp và giao chiến với tiểu thú biến dị.","detail":"Hàn Lập giao chiến với tiểu thú tại đây, sau đó tìm kiếm nó trong phạm vi vài trăm dặm nhưng không phát hiện tung tích nên rời khỏi khu vực.","theLucLienQuan":[],"nguon":["@c1296"]},{"id":"tieu-coc-duoi-chan-nui","name":"Tiểu cốc dưới chân núi","cn":"","capDo":"khac","parentId":"phien-son-mach","blurb":"Cốc nhỏ được Hàn Lập chọn làm nơi lĩnh hội cảm ngộ sau trận chiến.","detail":"Hàn Lập khoanh chân đả tọa tại đây suốt ba ngày ba đêm. Hắn có thu hoạch nhưng chưa thể phá vỡ bình cảnh.","theLucLienQuan":[],"nguon":["@c1296"]},{"id":"ho-nuoc-lon","name":"Hồ nước lớn","cn":"","capDo":"khac","parentId":null,"blurb":"Hồ nước nơi nhóm Luyện Thể sĩ và đàn quái xà bị một đợt thủy tiễn tập kích.","detail":"Sau khi thủy tiễn tiêu diệt gần hết người và quái xà ven bờ, Xà Vương bị ngân thủ giết chết. Thủy Mị, Thiết Nhận và một Hỏa nhân sau đó lần lượt xuất hiện tại đây.","theLucLienQuan":["Nhân tộc"],"nguon":["@c1296"]},{"id":"hon-don-coc","name":"Hỗn Độn Cốc","cn":"","capDo":"vuc","parentId":null,"blurb":"Thung cốc nguy hiểm đang trở thành điểm hội tụ của Linh Tộc, Nhân tộc và Yêu tộc.","detail":"Kẻ phản nghịch mang Thần Huyết đã ẩn vào đây; Thiên Anh và Hoàng Thạch Công trấn giữ bên trong, Yêu tộc phong tỏa cốc khẩu, còn đoàn Hoàng Lương Linh Quân đang tiến tới. Trong cốc có Chích Quang Đàm bí ẩn và lưu truyền lời đồn về Thượng Cổ Cự Nhân.","theLucLienQuan":["Linh Tộc","Yêu tộc","Nhân tộc","Hắc Phượng Tộc","Khí Linh Tộc","Ngũ Hành Linh Tộc"],"nguon":["@c1297"]},{"id":"chich-quang-dam","name":"Chích Quang Đàm","cn":"","capDo":"khac","parentId":"hon-don-coc","blurb":"Đầm nước bí ẩn và cực kỳ nguy hiểm nằm trong Hỗn Độn Cốc.","detail":"Kẻ phản nghịch mang Thần Huyết đang ẩn dưới đầm. Ngay cả Thủy Mị có thần thông thủy tính và Lam thành chủ từng thăm dò Hỗn Độn Cốc cũng không dám chắc có thể xâm nhập an toàn.","theLucLienQuan":["Linh Tộc","Ngũ Hành Linh Tộc"],"nguon":["@c1297"]},{"id":"lac-duong-chi-mo","name":"Lạc Dương Chi Mộ","cn":"","capDo":"vuc","parentId":null,"blurb":"Khu vực được Hoàng Lương Linh Quân nhắc đến khi bác lời đồn về Thượng Cổ Cự Nhân.","detail":"Hoàng Lương Linh Quân cho rằng nếu Cự Nhân thật sự cư trú trong Hỗn Độn Cốc thì với bản tính hung bạo, nó đã sớm xông tới Lạc Dương Chi Mộ tàn sát.","theLucLienQuan":[],"nguon":["@c1297"]},{"id":"the-gioi-man-hoang","name":"Thế giới man hoang","cn":"","capDo":"vuc","parentId":"linh-gioi","blurb":"Vùng rộng lớn nằm ngoài lãnh địa của Nhân tộc và Yêu tộc, giàu thiên tài địa bảo nhưng vô cùng nguy hiểm.","detail":"Thế giới man hoang có nhiều tồn tại ngang tu sĩ Hóa Thần, Luyện Hư cùng những thiên tai khó dự đoán. Tu sĩ Nguyên Anh trở lên thường phải mạo hiểm tiến vào để tìm cơ duyên do tốc độ tu luyện chậm, nhưng số người có thể trở về chưa tới một phần ba.","theLucLienQuan":["Nhân tộc","Yêu tộc"],"nguon":["@c1298"]},{"id":"lac-duong","name":"Lạc Dương","cn":"","capDo":"thanh","parentId":"linh-gioi","blurb":"Nơi phía Nhân tộc từng bàn bạc kế hoạch và bị Huyễn Diễm Nga nghe trộm.","detail":"Tại Lạc Dương, Hoàn Thương Kì từng định mời Hoàng Lương Linh Quân đi Mãn Hoang. Huyễn Diễm Nga cũng nghe trộm cuộc bàn bạc của phía Nhân tộc tại đây, khiến kế hoạch mai phục ở Hỗn Độn cốc bị lộ.","theLucLienQuan":["Nhân tộc","Yêu tộc"],"nguon":["@c1300"]},{"id":"coc-khau-hon-don-coc","name":"Cốc khẩu Hỗn Độn Cốc","cn":"","capDo":"khac","parentId":"hon-don-coc","blurb":"Lối ra vào Hỗn Độn Cốc, bị bao phủ bởi sương mù dày đặc.","detail":"Lam Thành chủ hóa thành một đạo lam hồng chạy về phía cốc khẩu và nhanh chóng biến mất trong màn sương.","theLucLienQuan":["Nhân tộc"],"nguon":["@c1303"]},{"id":"ngoai-hon-don-coc","name":"Ngoài Hỗn Độn Cốc","cn":"","capDo":"khac","parentId":"hon-don-coc","blurb":"Khu vực bên ngoài Hỗn Độn Cốc, nơi từng diễn ra cuộc giao tranh giữa Húc Thiên với Hoàn Thiên Kỳ và Hoàng Lương Linh Quân.","detail":"Tại đây, Húc Thiên nhận thấy công pháp của Hoàn Thiên Kỳ và Hoàng Lương Linh Quân bổ khuyết lẫn nhau, tạo thành sức ép quá mạnh nên dẫn người Linh Tộc rút lui.","theLucLienQuan":["Linh Tộc"],"nguon":["@c1305"]},{"id":"man-hoang-chi-dia","name":"Man Hoang chi địa","cn":"","capDo":"vuc","parentId":"the-gioi-man-hoang","blurb":"Vùng đất rộng lớn có Thượng Cổ Cự Nhân sinh sống quần cư.","detail":"Hoàng Lương Linh Quân và Hoàn Thiên Kỳ từng giết một Song Diện Cự Nhân tại đây, sau đó bị ba Cự Nhân khác truy sát đến mức suýt phải chạy ra biển.","theLucLienQuan":[],"nguon":["@c1306","@c1324"]},{"id":"thien-vo-canh","name":"Thiên Vô Cảnh","cn":"","capDo":"vuc","parentId":null,"blurb":"Khu vực được Hoàng Lương Linh Quân nhắc đến khi suy đoán lai lịch của Hàn Lập.","detail":"Hoàng Lương Linh Quân nghi ngờ Hàn Lập có thể là tu sĩ đến từ khu vực lưỡng kính có liên quan tới Thiên Vô Cảnh, nhưng suy đoán này chưa được xác nhận.","theLucLienQuan":[],"nguon":["@c1308"]},{"id":"tieu-son-cach-chien-truong-hon-hai-nghin-dam","name":"Tiểu sơn cách chiến trường hơn hai nghìn dặm","cn":"","capDo":"khac","parentId":"man-hoang-chi-dia","blurb":"Một ngọn núi nhỏ cách chiến trường hơn hai nghìn dặm, nơi Hàn Lập đào thạch động để ẩn náu.","detail":"Hàn Lập lấp kín cửa thạch động, thu liễm hoàn toàn linh khí và ở lại đây nhiều tháng. Nhiều đạo thần niệm quét qua tiểu sơn nhưng không phát hiện được hắn.","theLucLienQuan":[],"nguon":["@c1309"]},{"id":"xuyen-van-son","name":"Xuyên Vân Sơn","cn":"","capDo":"khac","parentId":"man-hoang-chi-dia","blurb":"Một tòa cự sơn hoang vắng được thương đội của Hỏa lão chọn làm tuyến đường mới. Nơi đây có một bóng người bế quan suốt trăm năm và xuất hiện Thiên Kiếp bất thường trên đỉnh núi.","detail":"Yêu thú và thú dữ trong vòng ngàn dặm quanh Xuyên Vân Sơn được báo là đã bị thanh trừ, còn cự sơn cũng được các tu sĩ Kết Đan dò xét bằng thần niệm. Khi thương đội tiến đến chân núi, mây đen, hồ quang kim ngân và cuồng phong trắng đột ngột xuất hiện trên đỉnh, tạo thành thiên tượng không giống cả Tiểu Thiên Kiếp lẫn Đại Thiên Kiếp.","theLucLienQuan":["Thương hào của Hỏa lão"],"nguon":["@c1309"]},{"id":"cu-son-vo-danh","name":"Cự sơn vô danh","cn":"","capDo":"khac","parentId":"linh-gioi","blurb":"Ngọn núi nơi Hàn Lập tiềm tu hơn trăm năm và bất ngờ phải đối mặt với kim ngân lưỡng sắc thiên kiếp.","detail":"Cự sơn là trung tâm của dị tượng thiên kiếp lan rộng trong phạm vi trăm dặm. Ngân sắc điện hồ bóc mất từng mảng lớn trên đỉnh núi, còn kim sắc điện hồ xuyên qua núi đá để đánh thẳng vào lòng núi.","theLucLienQuan":[],"nguon":["@c1310"]},{"id":"bung-cu-son-vo-danh","name":"Bụng cự sơn vô danh","cn":"","capDo":"khac","parentId":"cu-son-vo-danh","blurb":"Nơi Hàn Lập tiềm tu, luyện Kim Cương Quyết đại thành và ngưng tụ lại Nguyên Anh từng bị hư hóa.","detail":"Hàn Lập ẩn tu trong bụng núi hơn trăm năm. Khi Nguyên Anh khôi phục, kim sắc thiên lôi xuyên qua lớp núi đá đánh thẳng vào bên trong, buộc hắn phải rời khỏi nơi này để ứng kiếp.","theLucLienQuan":[],"nguon":["@c1310"]},{"id":"phi-linh-thai","name":"Phi Linh Thai","cn":"","capDo":"khac","parentId":"linh-gioi","blurb":"Nơi tu sĩ từ hạ giới thông thường xuất hiện khi phi thăng lên Linh Giới.","detail":"Tu sĩ phi thăng sau khi xuất hiện tại Phi Linh Thai phải tới Thiên Uyên Thành. Hàn Lập không đến được nơi này vì gặp không gian phong bạo và bị cuốn vào vết nứt không gian.","theLucLienQuan":["Thiên Uyên Vệ"],"nguon":["@c1311"]},{"id":"thien-uyen-thanh","name":"Thiên Uyên Thành","cn":"","capDo":"thanh","parentId":"linh-gioi","blurb":"Thành trì mà các tu sĩ vừa phi thăng lên Linh Giới phải tới phục dịch.","detail":"Thiên Uyên Thành có lực lượng Thiên Uyên Vệ, sử dụng Thuyền Kim Đình và trang bị khắc Ngân Khoa Văn. Hai Thiên Uyên Vệ yêu cầu Hàn Lập theo họ tới đây sau khi phá lưỡng sắc lôi kiếp.","theLucLienQuan":["Thiên Uyên Vệ"],"nguon":["@c1311"]},{"id":"tam-canh-that-dia","name":"Tam Cảnh Thất Địa","cn":"","capDo":"vuc","parentId":null,"blurb":"Phạm vi do Tam Thánh Hoàng và Thất Yêu Vương cai quản, ngoại trừ Thiên Uyên Thành có địa vị độc lập.","detail":"Tam Cảnh Thất Địa nằm dưới cơ cấu cai quản của Tam Thánh Hoàng và Thất Yêu Vương. Thiên Uyên Thành là nơi duy nhất trong phạm vi này không phụ thuộc quyền quản lý của họ.","theLucLienQuan":["Tam Thánh Hoàng","Thất Yêu Vương","Thiên Uyên Thành"],"nguon":["@c1312"]},{"id":"phi-linh-dien","name":"Phi Linh Điện","cn":"","capDo":"khac","parentId":"thien-uyen-thanh","blurb":"Nơi Hàn Lập được đưa tới nghỉ ngơi sau khi đến Thiên Uyên Thành.","detail":"Sau chuỗi truyền tống đường dài, Hàn Lập được đại hán mắt xanh lục dẫn từ tế đàn truyền tống tới Phi Linh Điện theo lệnh của Kim Giáp tu sĩ.","theLucLienQuan":["Thiên Uyên Thành","Thiên Uyên Vệ"],"nguon":["@c1312"]},{"id":"te-dan-truyen-tong-thien-uyen-thanh","name":"Tế đàn truyền tống tại Thiên Uyên Thành","cn":"","capDo":"khac","parentId":"thien-uyen-thanh","blurb":"Một đài truyền tống cao khoảng hai ba mươi trượng trong cơ sở của Thiên Uyên Thành.","detail":"Đây là điểm cuối trong chuỗi khoảng hai mươi lần truyền tống của Kim Thuyền. Tế đàn được bốn Hắc Giáp tu sĩ cảnh giới Nguyên Anh canh giữ.","theLucLienQuan":["Thiên Uyên Thành"],"nguon":["@c1312"]},{"id":"thong-dao-da-den-thien-uyen-thanh","name":"Thông đạo đá đen","cn":"","capDo":"khac","parentId":"thien-uyen-thanh","blurb":"Thông đạo rộng khoảng năm sáu trượng, kéo sâu xuống khu vực phòng vệ của Thiên Uyên Thành.","detail":"Vách thông đạo có Ngân Khoa Văn ngăn thần niệm dò xét. Hàn Lập gặp nhiều Hắc Giáp tu sĩ và các Thanh Giáp tu sĩ thuộc Thanh Minh Vệ khi đi qua nơi này.","theLucLienQuan":["Thiên Uyên Thành","Thanh Minh Vệ"],"nguon":["@c1312"]},{"id":"phi-long-dien","name":"Phi Long Điện","cn":"","capDo":"khac","parentId":"thien-uyen-thanh","blurb":"Một cự tháp cao ngàn trượng trong quần thể kiến trúc dưới lòng đất của Thiên Uyên Thành.","detail":"Phi Long Điện có mười một tầng. Tầng bốn gồm các hành lang và nhiều gian phòng rộng như động phủ, có mật thất, phòng luyện đan, phòng luyện khí cùng cấm chế riêng; Hàn Lập được bố trí cư trú tại đây.","theLucLienQuan":["Thiên Uyên Thành"],"nguon":["@c1313"]},{"id":"quan-the-cu-thap-thien-uyen-thanh","name":"Quần thể cự tháp Thiên Uyên Thành","cn":"","capDo":"khac","parentId":"thien-uyen-thanh","blurb":"Khu vực kiến trúc khổng lồ nằm sâu dưới lòng đất của Thiên Uyên Thành.","detail":"Khu vực gồm một cự tháp rỗng ruột khổng lồ và hơn trăm tòa tháp khác nằm rải rác, với chiều cao từ khoảng trăm trượng tới ngàn trượng.","theLucLienQuan":["Thiên Uyên Thành"],"nguon":["@c1313"]},{"id":"ngoc-khuyet-cac","name":"Ngọc Khuyết Các","cn":"","capDo":"khac","parentId":"thien-uyen-thanh","blurb":"Địa điểm phụ trách thủ tục liên quan đến việc xây dựng động phủ trong Thiên Uyên Thành.","detail":"Triệu Vô Quy chỉ dẫn Hàn Lập tới Ngọc Khuyết Các để hỏi phương thức và thủ tục tự xây dựng động phủ.","theLucLienQuan":["Thiên Uyên Thành"],"nguon":["@c1314"]},{"id":"thuy-lang-son","name":"Thúy Lang Sơn","cn":"","capDo":"vuc","parentId":"thien-uyen-thanh","blurb":"Sơn mạch có linh khí dồi dào nhất trong ba khu linh địa được giới thiệu tại Ngọc Khuyết Các. Nơi đây tập trung nhiều động phủ Hóa Thần và sản sinh nhiều linh dược.","detail":"Thúy Lang Sơn có điều kiện linh khí tốt nhất trong ba sơn mạch dành cho việc lập động phủ. Hai linh địa vừa được thu hồi do chủ cũ chết vì thiên kiếp hoặc hết thọ nguyên đang trở thành mục tiêu tranh giành của nhiều tu sĩ Hóa Thần.","theLucLienQuan":["Ngọc Khuyết Các","Thiên Uyên Thành"],"nguon":["@c1315"]},{"id":"yeu-van-son","name":"Yêu Vận Sơn","cn":"","capDo":"vuc","parentId":"thien-uyen-thanh","blurb":"Sơn mạch liền kề Thúy Lang Sơn và thích hợp cho tu sĩ Hóa Thần lập động phủ. Linh khí tại đây kém hơn Thúy Lang Sơn.","detail":"Yêu Vận Sơn là một trong ba khu vực được Ngọc Khuyết Các giới thiệu cho Hàn Lập lựa chọn. Nơi này đáp ứng nhu cầu tu luyện của Hóa Thần nhưng không có linh khí dồi dào bằng Thúy Lang Sơn.","theLucLienQuan":["Ngọc Khuyết Các","Thiên Uyên Thành"],"nguon":["@c1315"]},{"id":"quynh-thien-son","name":"Quỳnh Thiên Sơn","cn":"","capDo":"vuc","parentId":"thien-uyen-thanh","blurb":"Khu linh địa vốn phù hợp hơn với tu sĩ Nguyên Anh và thiếu linh khí đối với Hóa Thần. Bù lại, động phủ tại đây thưa thớt và người lựa chọn có thể quản lý một vùng rất rộng.","detail":"Quỳnh Thiên Sơn không cung cấp đủ linh khí cho nhu cầu thông thường của tu sĩ Hóa Thần. Ưu thế của nơi này là mật độ động phủ thấp, cho phép người lập phủ chiếm phạm vi quản lý rộng khoảng vạn dặm.","theLucLienQuan":["Ngọc Khuyết Các","Thiên Uyên Thành"],"nguon":["@c1315"]},{"id":"vung-linh-dia-phia-tren-thuy-lan-son","name":"Vùng linh địa phía trên Thúy Lan Sơn","cn":"","capDo":"vuc","parentId":"thien-uyen-thanh","blurb":"Vùng linh địa rộng hơn hai vạn dặm với nhiều sơn mạch nối liền nhưng linh khí tương đối loãng.","detail":"Khu vực này nghèo linh dược và linh quặng nên ít người coi trọng. Hàn Lập lựa chọn nơi đây vì diện tích rộng và mức cạnh tranh thấp, nhưng cách gọi Thúy Lan Sơn trong đoạn mô tả chưa được xác nhận là đồng nhất với Thúy Lang Sơn.","theLucLienQuan":["Thiên Uyên Thành"],"nguon":["@c1316"]},{"id":"thien-van-son","name":"Thiên Vận Sơn","cn":"","capDo":"vuc","parentId":"thien-uyen-thanh","blurb":"Khu vực có các mảnh linh địa được đưa ra trong đợt tuyển chọn tại Thiên Uyên Thành.","detail":"Sau khi Kim huynh đánh dấu Thúy Lang Sơn, hai tu sĩ khác lần lượt chọn hai mảnh linh địa tại Thiên Vận Sơn, trong đó có một mảnh vốn chưa có chủ.","theLucLienQuan":["Thiên Uyên Thành"],"nguon":["@c1316"]},{"id":"linh-dia-tranh-doat","name":"Linh địa tranh đoạt","cn":"","capDo":"khac","parentId":"thien-uyen-thanh","blurb":"Vùng linh địa có linh khí khá loãng đang bị Hàn Lập và Hán tử họ Ông tranh giành.","detail":"Thầy trò Hán tử họ Ông nghi ngờ đây là nơi một nhân vật bí ẩn tọa hóa và có thể còn lưu lại di bảo cùng công pháp.","theLucLienQuan":["Thiên Uyên Thành"],"nguon":["@c1317"]},{"id":"tuong-thanh-huong-man-hoang","name":"Tường thành hướng man hoang","cn":"","capDo":"khac","parentId":"thien-uyen-thanh","blurb":"Tuyến phòng thủ kiên cố nhất của Thiên Uyên Thành, đối diện thế giới man hoang.","detail":"Tường thành dài hơn vài trăm dặm, cao hơn ngàn trượng, phủ phù chú và được quân đội nhân–yêu cùng các pháp trận cấm chế canh giữ liên tục. Phía sau tuyến thành duy trì hơn trăm vạn đại quân.","theLucLienQuan":["Thiên Uyên Thành","Nhân–yêu lưỡng tộc"],"nguon":["@c1317"]},{"id":"tuong-thanh-huong-tam-canh-that-yeu","name":"Tường thành hướng Tam cảnh thất yêu","cn":"","capDo":"khac","parentId":"thien-uyen-thanh","blurb":"Tuyến thành phục vụ giao thương và hoạt động xuất nhập ở phía Tam cảnh thất yêu.","detail":"Tuyến thành dài khoảng ngàn dặm, có mức canh phòng thấp hơn phía man hoang và là nơi đông đảo nhân tộc, yêu tộc qua lại để giao dịch hoặc tiến vào vùng hoang dã.","theLucLienQuan":["Thiên Uyên Thành","Nhân–yêu lưỡng tộc"],"nguon":["@c1317"]},{"id":"son-mach-ngoai-thien-uyen-thanh","name":"Sơn mạch ngoài Thiên Uyên Thành","cn":"","capDo":"vuc","parentId":"linh-gioi","blurb":"Vùng núi rộng lớn và liên tục bao quanh khu vực ngoài Thiên Uyên Thành.","detail":"Trong sơn mạch chỉ có một số thôn trấn phàm nhân nhỏ, không tồn tại tòa thành tu sĩ thứ hai.","theLucLienQuan":["Thiên Uyên Thành"],"nguon":["@c1317"]},{"id":"cac-thon-tran-nhan-loai-ngoai-thanh","name":"Các thôn trấn nhân loại ngoài thành","cn":"","capDo":"khac","parentId":"son-mach-ngoai-thien-uyen-thanh","blurb":"Những thôn trấn phàm nhân nhỏ nằm ngoài Thiên Uyên Thành.","detail":"Các thôn trấn cung cấp vật tư sinh hoạt, tu sĩ cấp thấp và luyện thể sĩ cấp thấp cho Thiên Uyên Thành.","theLucLienQuan":["Nhân tộc","Thiên Uyên Thành"],"nguon":["@c1317"]},{"id":"khu-vuc-yeu-toc-ngoai-thanh","name":"Khu vực yêu tộc ngoài thành","cn":"","capDo":"vuc","parentId":"son-mach-ngoai-thien-uyen-thanh","blurb":"Khu vực sinh sống của các đàn thú và yêu thú cấp thấp ngoài Thiên Uyên Thành.","detail":"Nơi đây có vài đàn thú lớn cùng nhiều yêu thú cấp thấp, giữ vai trò bổ sung lực lượng yêu tộc cấp thấp cho thành.","theLucLienQuan":["Yêu nhân lưỡng tộc","Thiên Uyên Thành"],"nguon":["@c1317"]},{"id":"thap-truong-lao-thien-uyen-thanh","name":"Tháp trưởng lão Thiên Uyên Thành","cn":"","capDo":"khac","parentId":"thien-uyen-thanh","blurb":"Tòa tháp lớn tại trung tâm thành nội, nơi lãnh đạo hai tộc cùng nghị sự.","detail":"Đây là địa điểm chung hiếm hoi của nhân tộc và yêu tộc, nơi hơn mười trưởng lão Hợp Thể kỳ thương nghị, quyết định đại sự và tạo thành chiến lực cuối cùng của Thiên Uyên Thành.","theLucLienQuan":["Thiên Uyên Thành","Trưởng Lão hội","Yêu nhân lưỡng tộc"],"nguon":["@c1317"]},{"id":"truong-lao-thap","name":"Trưởng Lão tháp","cn":"","capDo":"khac","parentId":"thien-uyen-thanh","blurb":"Thạch tháp cao vút trong mây tại Thiên Uyên thành, luôn có một trưởng lão Hợp Thể kỳ trấn thủ.","detail":"Trưởng Lão tháp nằm cách vị trí Hàn Lập quan sát hơn hai mươi dặm. Một trưởng lão Hợp Thể kỳ của nhân yêu lưỡng tộc thường xuyên trấn thủ bên trong.","theLucLienQuan":["Trưởng Lão hội","Yêu nhân lưỡng tộc","Thiên Uyên Thành"],"nguon":["@c1318"]},{"id":"nghiem-vu-dien","name":"Nghiễm Vũ điện","cn":"","capDo":"khac","parentId":"thien-uyen-thanh","blurb":"Địa điểm tổ chức cuộc tranh đoạt linh địa giữa Hàn Lập và hán tử họ Ông.","detail":"Nghiễm Vũ điện có một sân lớn lộ thiên được quang mạc cấm chế bao phủ. Người dự đấu thất bại nếu bị ép rời khỏi phạm vi cấm chế hoặc chủ động nhận thua.","theLucLienQuan":["Ngọc Khuyết Các","Thiên Uyên Thành"],"nguon":["@c1318"]},{"id":"khong-gian-am-hon-trong-thien-hon-linh","name":"Không gian âm hồn trong Thiên Hồn Linh","cn":"","capDo":"gioi-nho","parentId":null,"blurb":"Không gian riêng bên trong Thiên Hồn Linh, chứa hàng ngàn tinh hồn yêu thú và cấm chế áp chế sinh linh không mang âm hồn chi thể.","detail":"Không gian này có bốn cột bóng đen, tràn ngập tiếng quỷ khóc và chứa khoảng tám ngàn đến một vạn tinh hồn yêu thú hung ác. Chủ hồn vốn là thiên địa Linh thú cấp Hóa Thần trung kỳ, còn cấm chế tại đây hạn chế đáng kể pháp lực của sinh linh không phải âm hồn chi thể. Hàn Lập bị hút vào nhưng sau đó phá thủng không gian để thoát ra.","theLucLienQuan":[],"nguon":["@c1321"]},{"id":"linh-dia-han-lap-quynh-thien-son","name":"Linh địa của Hàn Lập tại Quỳnh Thiên Sơn","cn":"","capDo":"khac","parentId":"quynh-thien-son","blurb":"Linh địa rộng hơn hai vạn dặm do Hàn Lập vừa tiếp quản tại Quỳnh Thiên Sơn.","detail":"Khu vực không có tu sĩ khác cư trú, có một số mỏ linh thạch phẩm chất thấp và linh dược tự nhiên bình thường. Hàn Lập cắm pháp kỳ quanh ranh giới để xác lập quyền sở hữu, trong khi Minh lão ma đang mưu tính xâm nhập để tìm di bảo.","theLucLienQuan":["Thiên Uyên Thành"],"nguon":["@c1322"]},{"id":"dam-lay-chuong-khi-giua-hai-cu-son","name":"Đầm lầy chướng khí giữa hai cự sơn","cn":"","capDo":"khac","parentId":"linh-dia-han-lap-quynh-thien-son","blurb":"Vùng đầm lầy phủ chướng khí ngũ sắc nằm giữa hai ngọn núi lớn trong linh địa.","detail":"Chướng khí chứa kịch độc, cao hơn trăm trượng và có khả năng hạn chế thần niệm. Bên trong là một thạch cốc tự nhiên được Hàn Lập chọn làm nơi che giấu lối vào hai động phủ.","theLucLienQuan":[],"nguon":["@c1322"]},{"id":"hai-dong-phu-han-lap-quynh-thien-son","name":"Hai động phủ của Hàn Lập","cn":"","capDo":"khac","parentId":"dam-lay-chuong-khi-giua-hai-cu-son","blurb":"Hai động phủ được Hàn Lập đào sâu vào hai ngọn núi tại linh địa Quỳnh Thiên Sơn.","detail":"Một động phủ được dùng để đánh lạc hướng người ngoài, còn động phủ thật phục vụ tu luyện, trồng linh dược và nuôi linh thú, linh trùng. Các lối vào được che giấu nhờ thạch cốc cùng vùng chướng khí hạn chế thần niệm.","theLucLienQuan":[],"nguon":["@c1322"]},{"id":"duoc-vien-dong-phu-han-lap","name":"Dược viên trong động phủ thật","cn":"","capDo":"khac","parentId":"hai-dong-phu-han-lap-quynh-thien-son","blurb":"Khu trồng linh dược nằm trong động phủ thật của Hàn Lập.","detail":"Hàn Lập trồng lại tại đây toàn bộ linh chi và thảo mộc đã mang từ Nhân giới lên Linh giới.","theLucLienQuan":[],"nguon":["@c1322"]},{"id":"trung-that-dong-phu-han-lap","name":"Trùng Thất","cn":"","capDo":"khac","parentId":"hai-dong-phu-han-lap-quynh-thien-son","blurb":"Gian chuyên dụng để nuôi dưỡng linh trùng trong động phủ thật.","detail":"Hàn Lập đưa đàn Phệ Kim Trùng đang sắp tiến cấp thục thể vào Trùng Thất để tiếp tục nuôi dưỡng.","theLucLienQuan":[],"nguon":["@c1322"]},{"id":"thu-that-am-u","name":"Thú thất âm u","cn":"","capDo":"khac","parentId":"hai-dong-phu-han-lap-quynh-thien-son","blurb":"Một gian thú thất tối và âm u nằm trong động phủ thật của Hàn Lập.","detail":"Đây là nơi Hàn Lập mở Linh Thú Hoàn, phóng ra hắc hà và thả một con vật đen tuyền cao hơn một trượng.","theLucLienQuan":[],"nguon":["@c1322"]},{"id":"khong-gian-am-hon","name":"Không gian âm hồn","cn":"","capDo":"gioi-nho","parentId":null,"blurb":"Không gian có âm khí nồng đậm, chứa nhiều hung hồn và một Quỷ Vương.","detail":"Hàn Lập cùng Đề Hồn Thú từng giao chiến với vô số hung hồn và Quỷ Vương tại đây. Sau khi Quỷ Vương bị thôn phệ, Hàn Lập dùng Phá Diệt Pháp Mục xuyên thủng không gian để mang chiếc kén của Đề Hồn Thú thoát ra.","theLucLienQuan":[],"nguon":["@c1323"]},{"id":"linh-thu-that","name":"Linh thú thất","cn":"","capDo":"khac","parentId":"dong-phu-cua-han-lap","blurb":"Gian phòng trong động phủ dùng để bố trí linh thú.","detail":"Hàn Lập đặt chiếc kén đen do Đề Hồn Thú biến thành tại Linh thú thất trong thời gian linh thú tiến hóa.","theLucLienQuan":[],"nguon":["@c1323"]},{"id":"cu-thap-mau-xanh","name":"Cự tháp màu xanh","cn":"","capDo":"khac","parentId":"thien-uyen-thanh","blurb":"Công trình lớn trong Thiên Uyên Thành, nơi đặt Thiên Giáp Điện và khu vực đóng quân của Bính Đội.","detail":"Hàn Lập vào cự tháp để lĩnh Thanh Minh Giáp, sau đó đi qua nhiều tầng lầu tới đại điện của tiểu đội 56 Bính Đội.","theLucLienQuan":["Thiên Uyên Thành","Tiểu đội 56 Bính Đội"],"nguon":["@c1325"]},{"id":"thien-giap-dien","name":"Thiên Giáp Điện","cn":"","capDo":"khac","parentId":"cu-thap-mau-xanh","blurb":"Nơi cấp phát Thanh Minh Giáp trong cự tháp màu xanh của Thiên Uyên Thành.","detail":"Hàn Lập tới Thiên Giáp Điện lĩnh một bộ Thanh Minh Giáp trước khi đến trụ sở tiểu đội 56 nhận chức.","theLucLienQuan":["Thiên Uyên Thành"],"nguon":["@c1325"]},{"id":"dai-dien-binh-nam-muoi-sau","name":"Đại điện Bính năm mươi sáu","cn":"","capDo":"khac","parentId":"cu-thap-mau-xanh","blurb":"Trụ sở của tiểu đội 56 Bính Đội trong cự tháp màu xanh.","detail":"Đại điện nằm sau bảy tám tầng lầu, có linh quang cấm chế chắn cửa và các thông đạo dẫn tới khu tĩnh thất. Hàn Lập dùng ngọc bội đội trưởng mở cửa rồi gặp các thuộc hạ tại đây.","theLucLienQuan":["Tiểu đội 56 Bính Đội"],"nguon":["@c1325"]},{"id":"phu-le-chieu-trach","name":"Phù Lê Chiểu Trạch","cn":"","capDo":"vuc","parentId":"man-hoang-chi-dia","blurb":"Khu đầm lầy rộng lớn cách Thiên Uyên Thành khoảng vạn dặm, được xếp vào loại khu vực tuần tra nguy hiểm nhất.","detail":"Phù Lê Chiểu Trạch phủ đầy mê vụ và rộng đến mức độn quang theo một hướng hơn nửa tháng mới có thể ra khỏi. Địa hình đặc thù che đậy thần niệm ở mức độ nhất định, tạo điều kiện cho dị tộc ẩn núp giám thị Thiên Uyên Thành. Bốn đội tuần tra được phân công chia nhau dò xét khu vực này.","theLucLienQuan":["Thiên Uyên Thành","Ảnh Tộc"],"nguon":["@c1326"]},{"id":"bo-thuy-dam-co-thuy-truc","name":"Bờ thủy đàm có Thúy trúc","cn":"","capDo":"khac","parentId":"phu-le-chieu-trach","blurb":"Điểm nghỉ chân trong Phù Lê Chiểu Trạch có bãi đá, thủy đàm, cá bạc và hơn mười cây Thúy trúc.","detail":"Khung cảnh yên tĩnh tại đây thực chất là một lớp ngụy trang. Bãi đá là phần đầu phủ vảy đen của cự thú khổng lồ, còn những cây Thúy trúc xanh biếc là các xúc tu mọc trên thân nó; năng lực ẩn giấu này qua mặt cả thần niệm lẫn Dị Linh Bàn.","theLucLienQuan":["Đội tuần tra"],"nguon":["@c1327"]},{"id":"thuy-dam-do-cu-thu-bien-thanh","name":"Thủy đàm do cự thú biến thành","cn":"","capDo":"khac","parentId":"phu-le-chieu-trach","blurb":"Một thủy đàm cùng đàn cá bạc thực chất là hình thái ngụy trang của cự thú trong suốt.","detail":"Đàn ngân sắc tiểu ngư tụ thành đôi mắt, mặt nước hóa thành chiếc miệng lớn chứa đầy băng nhận rồi toàn bộ thủy đàm hiện nguyên hình thành cự thú. Dị thú âm thầm tập kích Hàn Lập nhưng bị Nguyên Từ Thần Quang trói và Nguyên Từ Thần Sơn trấn áp.","theLucLienQuan":[],"nguon":["@c1328"]},{"id":"thien-uyen-phuong-thi","name":"Thiên Uyên Phường Thị","cn":"","capDo":"khac","parentId":"thien-uyen-thanh","blurb":"Phường thị quy mô lớn trong Thiên Uyên Thành, hội tụ tài liệu từ Tam Cảnh Thất Yêu chi Địa và vật phẩm có nguồn gốc Man Hoang.","detail":"Không gian giao dịch được chia thành khu Nhân tộc, khu Yêu tộc và một đại điện trung tâm dùng chung. Nơi đây còn tổ chức cuộc đấu giá vật phẩm Man Hoang định kỳ ba năm một lần.","theLucLienQuan":["Nhân tộc","Yêu tộc","Thiên Uyên Thành"],"nguon":["@c1329"]},{"id":"dai-dien-trung-tam-phuong-thi","name":"Đại điện trung tâm phường thị","cn":"","capDo":"khac","parentId":"thien-uyen-phuong-thi","blurb":"Khu giao dịch chung giữa Nhân tộc và Yêu tộc tại Thiên Uyên Phường Thị.","detail":"Nhân tộc và Yêu tộc trao đổi các loại tài liệu hữu dụng cho hai bên tại đây. Khu vực đấu giá chiếm một phần tám toàn bộ đại điện.","theLucLienQuan":["Nhân tộc","Yêu tộc"],"nguon":["@c1329"]},{"id":"duoc-diem-tai-phuong-thi-thien-uyen","name":"Dược điếm tại phường thị Thiên Uyên","cn":"","capDo":"khac","parentId":"thien-uyen-phuong-thi","blurb":"Cửa hàng dược nhỏ lưu giữ hai phương thuốc tăng tiến tu vi Hóa Thần.","detail":"Dược điếm có một chưởng quỹ Kết Đan kỳ và hai người phục vụ Trúc Cơ kỳ. Cửa hàng giữ hai phương thuốc tăng tiến tu vi Hóa Thần nhưng không thể thu thập đầy đủ những tài liệu quá quý hiếm để phối chế.","theLucLienQuan":[],"nguon":["@c1329"]},{"id":"thai-huyen-dien","name":"Thái Huyền Điện","cn":"","capDo":"khac","parentId":"thien-uyen-phuong-thi","blurb":"Thạch điện lớn dành cho hoạt động trao đổi vật phẩm giữa Nhân Tộc và Yêu Tộc.","detail":"Thái Huyền Điện có cấm chế hạn chế pháp lực, cơ chế che giấu thân phận riêng cho hai tộc và lực lượng Kim Vệ cùng Thanh Minh Vệ duy trì trật tự. Người thuộc Nhân Tộc dùng ngọc bội tạo bạch hà, còn người thuộc Yêu Tộc dùng mặt nạ đen tạo yêu vân.","theLucLienQuan":["Nhân Tộc","Yêu Tộc","Kim Vệ","Thanh Minh Vệ"],"nguon":["@c1330"]},{"id":"dai-sanh-thai-huyen-dien","name":"Đại sảnh Thái Huyền Điện","cn":"","capDo":"khac","parentId":"thai-huyen-dien","blurb":"Không gian giao dịch chính bên trong Thái Huyền Điện.","detail":"Đại sảnh rộng vài trăm trượng và có hơn một trăm người được bạch hà hoặc hắc khí che thân. Hơn ba mươi người bày hàng dọc hai bên sảnh để trao đổi vật phẩm.","theLucLienQuan":["Nhân Tộc","Yêu Tộc"],"nguon":["@c1330"]},{"id":"tinh-that-trong-dien-phu-cua-tieu-doi","name":"Tĩnh thất trong điện phủ của tiểu đội","cn":"","capDo":"khac","parentId":"cu-thap-mau-xanh","blurb":"Tĩnh thất nơi Hàn Lập phong kín không gian để nghiên cứu lôi mộc.","detail":"Hàn Lập kích hoạt cấm chế sẵn có và bố trí thêm quang mạc che kín thạch bích trước khi kiểm tra đặc tính của lôi mộc, quan sát lôi văn và thử dùng Tịch Tà Thần Lôi mô phỏng kết cấu này.","theLucLienQuan":["Tiểu đội 56 Bính Đội"],"nguon":["@c1332"]},{"id":"than-dien-cua-tieu-doi-56","name":"Thần điện của tiểu đội 56","cn":"","capDo":"khac","parentId":null,"blurb":"Điện phủ thuộc tiểu đội 56, nơi Hàn Lập trở lại sau khi hoàn tất thử nghiệm lôi văn.","detail":"Cuộc tranh chấp giữa Hứa tiên tử và phe Hoàng Bảo diễn ra tại đây. Hàn Lập dùng thần niệm dò xét tình hình rồi tiến vào đại sảnh để can thiệp.","theLucLienQuan":["Tiểu đội 56 Bính Đội","Tiểu đội 27"],"nguon":["@c1333"]},{"id":"dai-sanh-than-dien-tieu-doi-56","name":"Đại sảnh thần điện tiểu đội 56","cn":"","capDo":"khac","parentId":"than-dien-cua-tieu-doi-56","blurb":"Đại sảnh nơi Hứa tiên tử và Trác Trùng đối đầu với Hoàng Bảo cùng đồ đệ.","detail":"Hàn Lập xuất hiện tại đây, nghe rõ nguyên nhân tranh chấp và yêu cầu hai bên tái hiện cuộc đối đầu giữa Băng Tinh Kiếm với Lục Ba Nhận.","theLucLienQuan":["Tiểu đội 56 Bính Đội","Tiểu đội 27"],"nguon":["@c1333"]},{"id":"dien-phu","name":"Điện phủ","cn":"","capDo":"khac","parentId":null,"blurb":"Nơi diễn ra cuộc giao đấu bằng bổn mạng pháp bảo giữa Hứa tiên tử và đồ đệ Hoàng Bảo.","detail":"Tại điện phủ, Hàn Lập gia trì Băng Tinh Kiếm cho Hứa tiên tử và bí mật thi triển Tâm Hàn Nhập Thể. Hoàng Bảo cứu đồ đệ, nhận thua rồi hủy bỏ chuyện cầu thân trước khi rời đi.","theLucLienQuan":[],"nguon":["@c1334"]},{"id":"cu-sanh-dau-gia","name":"Cự sảnh đấu giá","cn":"","capDo":"khac","parentId":"thai-huyen-dien","blurb":"Đại sảnh rộng hơn nghìn trượng bên trong Thái Huyền Điện, nơi diễn ra kỳ đấu giá.","detail":"Cự sảnh chứa gần một nghìn Phi Thiên Thạch Ốc lơ lửng và một đấu giá đài cao hơn mười trượng. Các thạch ốc được bố trí biệt lập nhằm ngăn thần niệm và bảo vệ thân phận người tham gia.","theLucLienQuan":["Hội đấu giá Thái Huyền Điện"],"nguon":["@c1335"]},{"id":"man-hoang-the-gioi","name":"Man Hoang thế giới","cn":"","capDo":"vuc","parentId":null,"blurb":"Vùng đất Man Hoang được nhắc đến như nguồn gốc của một loại tài liệu cực phẩm.","detail":"Một tài liệu cực phẩm lấy từ nơi này được chọn làm một trong ba vật phẩm áp trục của hội đấu giá tại Thái Huyền Điện.","theLucLienQuan":[],"nguon":["@c1335"]},{"id":"dai-sanh-dau-gia","name":"Đại sảnh đấu giá","cn":"","capDo":"khac","parentId":"thai-huyen-dien","blurb":"Nơi diễn ra việc kiểm nghiệm lân phiến Mặc Kỳ Lân và cuộc tranh giá bảo vật.","detail":"Tam đại giám định sư lên đài tại đây để phụ trách ba bảo vật trân quý cuối cùng. Thủy linh khí từ lân phiến Mặc Kỳ Lân lan khắp đại sảnh trước khi giá đấu nhanh chóng vượt hai ngàn vạn linh thạch.","theLucLienQuan":["Hội đấu giá Thái Huyền Điện"],"nguon":["@c1337"]},{"id":"phi-thien-thach-oc-cua-han-lap","name":"Phi Thiên Thạch Ốc của Hàn Lập","cn":"","capDo":"khac","parentId":"cu-sanh-dau-gia","blurb":"Gian thạch ốc dành cho Hàn Lập trong đại hội đấu giá.","detail":"Thạch ốc được phù văn bao quanh, là nơi Hàn Lập tham gia tranh giá và trực tiếp giao số linh thảo quý hiếm để nhận ba miếng Chân Linh Lân Phiến.","theLucLienQuan":["Hội đấu giá Thái Huyền Điện"],"nguon":["@c1338"]},{"id":"dau-gia-dai","name":"Đấu giá đài","cn":"","capDo":"khac","parentId":"cu-sanh-dau-gia","blurb":"Khu vực trung tâm dùng để giới thiệu và biểu diễn vật phẩm đấu giá.","detail":"Tại đây, người chủ trì công bố kết quả giao dịch Chân Linh Lân Phiến, đưa Bình Hải Qua ra biểu diễn và tổ chức cuộc tranh giá tiếp theo.","theLucLienQuan":["Hội đấu giá Thái Huyền Điện"],"nguon":["@c1338"]},{"id":"tam-canh","name":"Tam Cảnh","cn":"","capDo":"vuc","parentId":null,"blurb":"Khu vực có hoạt động đấu giá bị Lũng gia thao túng.","detail":"Công tử Lũng gia cho biết gia tộc mình kiểm soát hoạt động đấu giá trên phạm vi Tam Cảnh và dùng mạng lưới này trong kế hoạch dò tìm người mang Thiên Phượng Huyết Mạch.","theLucLienQuan":["Lũng gia"],"nguon":["@c1339"]},{"id":"son-mach-dat-dong-phu-han-lap","name":"Sơn mạch đặt động phủ Hàn Lập","cn":"","capDo":"khac","parentId":null,"blurb":"Sơn mạch nơi đặt động phủ mà Hàn Lập trở về sau khi rời Thiên Uyên Thành.","detail":"Khi Hàn Lập bay tới gần sơn mạch sau vài ngày, tại nơi cách động phủ hơn nghìn dặm có hai người chưa rõ danh tính đang căng thẳng giằng co.","theLucLienQuan":[],"nguon":["@c1339"]},{"id":"thach-son-trong-linh-dia-han-lap","name":"Thạch sơn trong linh địa của Hàn Lập","cn":"","capDo":"khac","parentId":"linh-dia-han-lap-quynh-thien-son","blurb":"Ngọn núi đá trơ trụi nằm trong linh địa của Hàn Lập, khác biệt với vùng linh mạch xanh tốt xung quanh.","detail":"Đỉnh núi được tám quang trụ cùng Tứ Phương Pháp Trận che giấu. Bên dưới thạch sơn tồn tại một quang đoàn lam nhạt có khả năng truyền tống người xâm nhập vào không gian kỳ bí.","theLucLienQuan":["Thiên Uyên Thành"],"nguon":["@c1343"]},{"id":"khong-gian-ky-bi-duoi-thach-son","name":"Không gian kỳ bí dưới thạch sơn","cn":"","capDo":"gioi-nho","parentId":"thach-son-trong-linh-dia-han-lap","blurb":"Không gian bí ẩn nằm dưới thạch sơn trong linh địa của Hàn Lập.","detail":"Không gian cao gần trăm trượng và rộng khoảng một dặm, bốn phía phủ thất sắc quang hà. Trên cao có bảy quang đoàn tỏa ánh sáng trắng ngà như những mặt trời, còn trung tâm là một quang môn thất sắc dẫn sâu vào cấm chế.","theLucLienQuan":[],"nguon":["@c1343"]},{"id":"quang-mon-that-sac","name":"Quang môn thất sắc","cn":"","capDo":"khac","parentId":"khong-gian-ky-bi-duoi-thach-son","blurb":"Cổng vòm thất sắc nằm giữa bảy quang đoàn trên bầu trời của không gian kỳ bí.","detail":"Bên trong quang môn mờ ảo và dẫn tới khu vực sâu hơn của cấm chế. Hai trưởng bối Luyện Hư của Kim Bàn Tử và Hán tử họ Ông đã tiến qua đây để tiếp tục thăm dò.","theLucLienQuan":[],"nguon":["@c1343"]},{"id":"khong-gian-ky-bi-sau-quang-mon","name":"Không gian kỳ bí sau quang môn","cn":"","capDo":"gioi-nho","parentId":null,"blurb":"Không gian phía sau quang môn thất sắc, thực chất là nơi giam giữ Ngọc Cốt Nhân Ma.","detail":"Vách không gian được bao phủ bởi thất sắc hào quang có thể nuốt thần niệm và sinh ra lực hút mạnh. Sau khi cấm chế Thượng Cổ bị chấn động và Ngọc Cốt Nhân Ma thoát ra, hào quang trên vách tan rã, quang môn vặn vẹo và toàn bộ không gian bắt đầu sụp đổ.","theLucLienQuan":[],"nguon":["@c1344"]},{"id":"khong-gian-sau-chuong-bich","name":"Không gian sau chướng bích","cn":"","capDo":"khac","parentId":null,"blurb":"Không gian giam giữ nhóm Hàn Lập, được ngăn với bên ngoài bởi một tầng chướng bích.","detail":"Bên trong khu vực có quang môn đang vặn vẹo và Ngọc Cốt Nhân Ma sắp vượt qua. Minh lão ma cùng Kim lão quái hợp lực tạo một thông đạo tạm thời trên chướng bích để thoát ra ngoài.","theLucLienQuan":[],"nguon":["@c1345"]},{"id":"thach-son","name":"Thạch sơn","cn":"","capDo":"khac","parentId":"son-mach-dat-dong-phu-han-lap","blurb":"Ngọn núi nơi nhóm Hàn Lập xuất hiện sau khi vượt qua thông đạo trên chướng bích.","detail":"Không gian quanh quang cầu phía trên thạch sơn trở nên bất ổn, xuất hiện vô số nếp gấp và hắc ti trước khi phong bạo bùng phát, nghiền nát và thôn phệ mọi vật trong phạm vi ảnh hưởng.","theLucLienQuan":[],"nguon":["@c1345"]},{"id":"ho-lon-tai-thach-son-cu","name":"Hố lớn tại thạch sơn cũ","cn":"","capDo":"khac","parentId":"linh-dia-han-lap-quynh-thien-son","blurb":"Hố lớn hình thành sau khi không gian phong bạo xóa sổ tòa thạch sơn tại linh địa của Hàn Lập.","detail":"Không gian phong bạo san bằng tòa thạch sơn cũ và để lại một hố lớn có đường kính hơn trăm trượng. Hai Thiên Vệ kim giáp về sau tới khu vực này kiểm tra dấu vết không gian dao động.","theLucLienQuan":["Thiên Uyên Thành"],"nguon":["@c1346"]},{"id":"khu-rung-cach-hien-truong-hon-ba-tram-dam","name":"Khu rừng cách hiện trường hơn ba trăm dặm","cn":"","capDo":"khac","parentId":"linh-dia-han-lap-quynh-thien-son","blurb":"Khu rừng nơi bạch ngọc cốt thủ ẩn náu sau khi thoát khỏi không gian phong bạo.","detail":"Hàn Lập lần theo dị vật tới khu rừng cách hiện trường hơn ba trăm dặm, dùng quang thủ ép nó hiện thân rồi lấy Hỏa Linh Ti bắt giữ và luyện hóa.","theLucLienQuan":[],"nguon":["@c1346"]},{"id":"bai-loan-thach-co-bot-khi-tim","name":"Bãi loạn thạch có bọt khí tím","cn":"","capDo":"khac","parentId":null,"blurb":"Bãi loạn thạch nằm cách vị trí ban đầu của tiểu đội Hắc Thiết Vệ hơn mười dặm, có những bọt khí màu tím xuất hiện quanh khu vực.","detail":"Thần niệm không thể xuyên xuống bãi loạn thạch, khiến Hắc Thiết Vệ phải dùng khôi lỗi thiết phong dò xét. Lục Ảnh lợi dụng khu vực này để ẩn nấp áp sát và phục kích tiểu đội.","theLucLienQuan":["Hắc Thiết Vệ","Ảnh Tộc"],"nguon":["@c1348"]},{"id":"tang-cot-sa-mac","name":"Táng Cốt Sa Mạc","cn":"","capDo":"khac","parentId":null,"blurb":"Khu vực tuần tra do Yêu Tộc phụ trách, nằm trong vùng hoạt động quanh Thiên Uyên Thành.","detail":"Táng Cốt Sa Mạc gần đây xuất hiện nhiều thám tử và Hóa Hình Yêu Tộc. Các đội tuần tra khác đã chịu thương vong tại đây, góp phần làm dấy lên nghi vấn Dị Tộc đang chuẩn bị một đợt tiến công.","theLucLienQuan":["Yêu Tộc","Dị Tộc"],"nguon":["@c1349"]},{"id":"thien-nghiem-dien","name":"Thiên Nghiễm Điện","cn":"","capDo":"khac","parentId":"thien-uyen-thanh","blurb":"Nơi các trưởng lão định kỳ giảng đạo, thường khoảng mười năm mới tổ chức một lần.","detail":"Hàn Lập dùng công trạng bắt sống Lục Ảnh để giành tư cách vào Thiên Nghiễm Điện nghe Hình trưởng lão giảng Phù Lê Chi Thuật sau nửa tháng.","theLucLienQuan":["Thiên Uyên Thành","Luận Công Các"],"nguon":["@c1350"]},{"id":"cu-thap-thien-uyen-thanh","name":"Cự tháp Thiên Uyên Thành","cn":"","capDo":"khac","parentId":"thien-uyen-thanh","blurb":"Cự tháp trong Thiên Uyên Thành, vừa là nơi trú đóng của tiểu đội vừa có khu vực tiếp nhận tù binh.","detail":"Sau khi kết thúc tuần tra, tiểu đội Hàn Lập trở về cự tháp. Hàn Lập sau đó lên tầng mười để giao Lục Ảnh bị bắt sống cho Văn tiền bối.","theLucLienQuan":["Thiên Uyên Thành","Đội tuần tra"],"nguon":["@c1350"]},{"id":"tang-muoi-cu-thap","name":"Tầng mười cự tháp","cn":"","capDo":"khac","parentId":"cu-thap-thien-uyen-thanh","blurb":"Khu vực làm việc của Văn tiền bối trong cự tháp Thiên Uyên Thành.","detail":"Đại sảnh tại tầng mười được bảo vệ bởi nhiều tầng cấm chế và có thạch bàn gắn pháp trận. Văn tiền bối dùng pháp trận tại đây để tiếp nhận rồi truyền tống ngọc hạp chứa Lục Ảnh tới nơi giam giữ.","theLucLienQuan":["Thiên Uyên Thành"],"nguon":["@c1350"]},{"id":"thien-trac-giam-phuong-thi","name":"Thiên Trắc Giảm phường thị","cn":"","capDo":"thanh","parentId":"thien-uyen-thanh","blurb":"Phường thị mà Hàn Lập tới sau khi rời cự tháp.","detail":"Thái Huyền Điện nằm trong phường thị này và được dùng làm nơi giao dịch bí mật giữa tu sĩ Nhân Tộc cùng Yêu Tộc.","theLucLienQuan":["Thiên Uyên Thành"],"nguon":["@c1350"]},{"id":"that-dia","name":"Thất Địa","cn":"","capDo":"vuc","parentId":"linh-gioi","blurb":"Khu vực được nhắc đến như nguồn điều động thêm tu sĩ tới Thiên Uyên Thành.","detail":"Theo tin tức của Viêm đạo hữu, nhiều tu sĩ có tu vi không thấp từ Thất Địa đang được điều tới Thiên Uyên Thành giữa lúc nguy cơ dị tộc công thành gia tăng.","theLucLienQuan":["Thiên Uyên Thành"],"nguon":["@c1350"]},{"id":"thach-thap-cua-han-lap","name":"Thạch Tháp của Hàn Lập","cn":"","capDo":"khac","parentId":"thien-uyen-thanh","blurb":"Nơi Hàn Lập trở về sau khi rời Thái Huyền Điện.","detail":"Tại Thạch Tháp, Hàn Lập đổi Ngọc Bài ghi công trạng thành lệnh bài rồi nghỉ trong tĩnh thất ba ngày trước khi tới cuộc tụ hội bí mật.","theLucLienQuan":["Thiên Uyên Thành"],"nguon":["@c1351"]},{"id":"son-coc-tu-hoi-ngoai-thien-uyen-thanh","name":"Sơn cốc tụ hội ngoài Thiên Uyên Thành","cn":"","capDo":"khac","parentId":"thien-uyen-thanh","blurb":"Sơn cốc xanh tươi bên ngoài Thiên Uyên Thành, nơi che giấu lối vào cuộc tụ hội của các phi thăng tu sĩ.","detail":"Một thông đạo bí mật được giấu trong thạch bích của sơn cốc. Hàn Lập dùng kim phù mở lối rồi vượt qua quang mạc trước bạch ngọc đại môn để tiến vào nơi tụ hội.","theLucLienQuan":["Phi thăng tu sĩ tại Thiên Uyên Thành"],"nguon":["@c1351"]},{"id":"phong-tu-hoi-trong-thach-bich","name":"Phòng tụ hội trong thạch bích","cn":"","capDo":"khac","parentId":"son-coc-tu-hoi-ngoai-thien-uyen-thanh","blurb":"Gian phòng bí mật dùng làm nơi tụ hội của các phi thăng tu sĩ.","detail":"Gian phòng rộng hơn ba mươi trượng, bên trong đặt bàn đá và hơn hai mươi ghế đá. Khoảng mười lăm đến mười sáu tu sĩ Hóa Thần tề tựu tại đây dưới sự chủ trì của Văn tu sĩ và Triệu Vô Quy.","theLucLienQuan":["Phi thăng tu sĩ tại Thiên Uyên Thành"],"nguon":["@c1351"]},{"id":"thien-linh-kinh","name":"Thiên Linh Kính","cn":"","capDo":"khac","parentId":"linh-gioi","blurb":"Nơi xuất thân của Hình trưởng lão, người nổi danh trong Tam Cảnh nhờ Phù Lê Chi Thuật.","detail":"Thiên Linh Kính được nhắc đến khi Văn tiền bối giới thiệu lai lịch của Hình trưởng lão trước buổi giảng tại Thiên Nghiễm Điện.","theLucLienQuan":[],"nguon":["@c1350"]},{"id":"thach-thap","name":"Thạch Tháp","cn":"","capDo":"khac","parentId":"thien-uyen-thanh","blurb":"Thạch tháp có tĩnh thất được Hàn Lập sử dụng để tu luyện.","detail":"Hàn Lập trở lại tĩnh thất trong Thạch Tháp, bố trí cấm chế rồi tiến hành tu luyện. Tại đây, Nguyên Anh của hắn xuất khiếu và nhiều dị tượng xuất hiện trên hai bàn tay cùng phía sau lưng.","theLucLienQuan":["Thiên Uyên Thành"],"nguon":["@c1353"]}]};
